            C++

    #include <iostream>
#include <unordered_map>
#include <vector>
using namespace std;

bool checkEqual(vector<int>& a, vector<int>& b) {
  	int n = a.size(), m = b.size();
    if (n != m)
        return false;

    unordered_map<int, int> mp;
    for (int i = 0; i < n; i++)
        mp[a[i]]++;

    for (int i = 0; i < n; i++) {
        if (mp.find(b[i]) == mp.end())
            return false;

        if (mp[b[i]] == 0)
            return false;

        mp[b[i]]--;
    }
    return true;
}

int main() {
    vector<int> a = { 3, 5, 2, 5, 2 };
    vector<int> b = { 2, 3, 5, 5, 2 };

    if (checkEqual(a, b))
        cout << "true";
    else
        cout << "false";
    return 0;
}


            Java

    import java.io.*;
import java.util.*;

class GfG {

    public static boolean checkEqual(int a[], int b[]) {
        int n = a.length, m = b.length;
        if (n != m)
            return false;

        Map<Integer, Integer> map
            = new HashMap<Integer, Integer>();
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (map.get(a[i]) == null)
                map.put(a[i], 1);
            else {
                count = map.get(a[i]);
                count++;
                map.put(a[i], count);
            }
        }

        for (int i = 0; i < n; i++) {

            if (!map.containsKey(b[i]))
                return false;

            if (map.get(b[i]) == 0)
                return false;

            count = map.get(b[i]);
            --count;
            map.put(b[i], count);
        }

        return true;
    }

    public static void main(String[] args) {
        int a[] = { 3, 5, 2, 5, 2 };
        int b[] = { 2, 3, 5, 5, 2 };

        if (checkEqual(a, b))
            System.out.println("true");
        else
            System.out.println("false");
    }
}


